<template><main class="hh-page billing-page"><section class="billing-hero"><div><span>FACTURACIÓN HOSPITALARIA</span><h1>{{config.title}}</h1><p>{{config.help}}</p></div><div><router-link to="/facturacion/cuentas" class="btn btn-outline-light">Cuentas</router-link><button class="btn btn-light text-primary" :disabled="loading" @click="load"><i class="ph ph-arrows-clockwise"></i></button></div></section><nav class="billing-nav"><router-link v-for="item in nav" :key="item.path" :to="item.path"><i :class="item.icon"></i>{{item.label}}</router-link></nav><section v-if="section==='dashboard'" class="metrics"><article v-for="metric in metrics" :key="metric.label"><span><i :class="metric.icon"></i></span><div><small>{{metric.label}}</small><strong>{{metric.value}}</strong></div></article></section><section class="billing-card"><header><div><small>{{config.eyebrow}}</small><h2>{{config.listTitle}}</h2></div><div class="filters"><input v-model.trim="filters.buscar" class="form-control" placeholder="Paciente, orden, factura o pagador" @keyup.enter="load"><select v-model="filters.estado" class="form-select" @change="load"><option value="">Todos los estados</option><option v-for="state in config.states" :key="state">{{state}}</option></select></div></header><div v-if="error" class="alert alert-danger m-3">{{error}}<small class="d-block mt-1">El endpoint de listado debe estar disponible en el backend para esta bandeja.</small></div><div v-if="loading" class="state"><span class="spinner-border text-primary"></span><p>Consultando información…</p></div><div v-else-if="!rows.length" class="state"><i :class="config.icon"></i><h3>Sin registros</h3><p>No hay información para los filtros seleccionados.</p></div><div v-else class="records"><article v-for="(row,index) in rows" :key="row.id||index"><span><i :class="config.icon"></i></span><div><small>{{status(row)}}</small><strong>{{title(row)}}</strong><p>{{detail(row)}}</p></div><div class="amount"><small>VALOR</small><strong>{{money(row.total||row.valor||row.saldo)}}</strong></div><router-link v-if="detailRoute(row)" :to="detailRoute(row)" class="btn btn-sm btn-outline-primary">Ver detalle</router-link></article></div></section></main></template>
<script setup>
import{computed,onMounted,reactive,ref,watch}from'vue';import{useRoute}from'vue-router';import{obtenerMensajeError}from'@/services/api';import{listarRecursoFacturacion}from'@/services/facturacion';
const route=useRoute(),rows=ref([]),loading=ref(false),error=ref(''),filters=reactive({buscar:'',estado:''}),nav=[{path:'/facturacion',label:'Resumen',icon:'ph ph-squares-four'},{path:'/facturacion/cuentas',label:'Cuentas',icon:'ph ph-folder-open'},{path:'/facturacion/cargos',label:'Cargos',icon:'ph ph-list-checks'},{path:'/facturacion/auditoria',label:'Auditoría',icon:'ph ph-shield-check'},{path:'/facturacion/facturas',label:'Facturas',icon:'ph ph-receipt'},{path:'/facturacion/transmisiones',label:'FEV/RIPS',icon:'ph ph-paper-plane-tilt'},{path:'/facturacion/radicaciones',label:'Radicación',icon:'ph ph-stamp'},{path:'/facturacion/glosas',label:'Glosas',icon:'ph ph-warning-circle'},{path:'/facturacion/cartera',label:'Cartera',icon:'ph ph-wallet'}],configs={dashboard:{title:'Centro de facturación',help:'Controle cuentas, cargos, facturas, radicaciones y cartera desde un solo lugar.',eyebrow:'OPERACIÓN RECIENTE',listTitle:'Cuentas que requieren atención',resource:'cuentas',icon:'ph ph-chart-line-up',states:['ABIERTA','EN_AUDITORIA']},accounts:{title:'Cuentas hospitalarias',help:'Audite el episodio económico de cada orden de trabajo.',eyebrow:'LIBRO MAYOR',listTitle:'Cuentas por episodio y pagador',resource:'cuentas',icon:'ph ph-folder-open',states:['ABIERTA','EN_AUDITORIA','CERRADA','FACTURADA','REABIERTA','ANULADA']},charges:{title:'Libro de cargos',help:'Consulte los hechos económicos generados por prestaciones y consumos.',eyebrow:'TRAZABILIDAD ECONÓMICA',listTitle:'Cargos hospitalarios',resource:'cargos',icon:'ph ph-list-checks',states:['BORRADOR','VALIDADO','LIQUIDADO','FACTURADO','RECHAZADO','ANULADO']},audit:{title:'Auditoría de cuentas',help:'Resuelva inconsistencias antes de liquidar y cerrar.',eyebrow:'CONTROL PREVIO',listTitle:'Cuentas con hallazgos',resource:'auditoria',icon:'ph ph-shield-check',states:['PENDIENTE','CON_HALLAZGOS','VALIDADA']},invoices:{title:'Facturas',help:'Gestione emisión, validación y seguimiento de facturas.',eyebrow:'DOCUMENTOS COMERCIALES',listTitle:'Facturas hospitalarias',resource:'facturas',icon:'ph ph-receipt',states:['BORRADOR','EMITIDA','VALIDADA_DIAN','VALIDADA_RIPS','RADICADA','GLOSADA','PAGADA']},transmissions:{title:'Transmisiones FEV/RIPS',help:'Consulte intentos y respuestas de validación electrónica.',eyebrow:'INTEROPERABILIDAD',listTitle:'Envíos y respuestas',resource:'transmisiones',icon:'ph ph-paper-plane-tilt',states:['PENDIENTE','VALIDADA','RECHAZADA']},filings:{title:'Radicaciones',help:'Controle número único, receptor y fecha de radicación.',eyebrow:'PRESENTACIÓN AL PAGADOR',listTitle:'Facturas radicadas',resource:'radicaciones',icon:'ph ph-stamp',states:['PENDIENTE','RADICADA','DEVUELTA']},glosses:{title:'Glosas y devoluciones',help:'Registre objeciones, respuestas y conciliaciones.',eyebrow:'AUDITORÍA DEL PAGADOR',listTitle:'Casos de glosa',resource:'glosas',icon:'ph ph-warning-circle',states:['ABIERTA','RESPONDIDA','ACEPTADA','CONCILIADA']},portfolio:{title:'Pagos y cartera',help:'Consulte recaudos, aplicaciones y saldos pendientes.',eyebrow:'CARTERA',listTitle:'Saldos por factura',resource:'cartera',icon:'ph ph-wallet',states:['PENDIENTE','PAGADA_PARCIAL','PAGADA']},settings:{title:'Parametrización de facturación',help:'Configure reglas generales y adaptadores del módulo.',eyebrow:'CONFIGURACIÓN',listTitle:'Parámetros vigentes',resource:'parametrizacion',icon:'ph ph-gear',states:['ACTIVO','INACTIVO']}},section=computed(()=>route.meta.billingSection||'dashboard'),config=computed(()=>configs[section.value]),array=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:Array.isArray(v?.items)?v.items:[],status=r=>r.estado||r.status||'Pendiente',title=r=>r.paciente||r.nombre||r.numero_factura||`Registro #${r.id}`,detail=r=>[r.pagador||r.tercero,r.id_orden_trabajo?`Orden #${r.id_orden_trabajo}`:''].filter(Boolean).join(' · ')||'Sin información adicional',money=v=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(Number(v||0)),detailRoute=r=>section.value==='accounts'||section.value==='dashboard'?`/facturacion/cuentas/${r.id}`:section.value==='invoices'?`/facturacion/facturas/${r.id}`:section.value==='glosses'?`/facturacion/glosas/${r.id}`:'';
const metrics=computed(()=>[{label:'Cuentas abiertas',value:rows.value.filter(r=>/ABIERTA|REABIERTA/.test(status(r))).length,icon:'ph ph-folder-open'},{label:'En auditoría',value:rows.value.filter(r=>/AUDITORIA/.test(status(r))).length,icon:'ph ph-shield-check'},{label:'Por facturar',value:rows.value.filter(r=>/CERRADA/.test(status(r))).length,icon:'ph ph-receipt'},{label:'Alertas',value:rows.value.filter(r=>r.alertas?.length||r.hallazgos?.length).length,icon:'ph ph-warning'}]);async function load(){loading.value=true;error.value='';try{rows.value=array(await listarRecursoFacturacion(config.value.resource,filters))}catch(e){rows.value=[];error.value=obtenerMensajeError(e)}finally{loading.value=false}}watch(section,load);onMounted(load)
</script>
<style scoped>.billing-hero{display:flex;align-items:center;justify-content:space-between;padding:1.45rem 1.55rem;border-radius:1rem;background:linear-gradient(120deg,#123f68,#118aa6);color:#fff}.billing-hero>div:last-child{display:flex;gap:.5rem}.billing-hero span,.billing-card header small{font-size:.68rem;font-weight:800;letter-spacing:.08em}.billing-hero h1{margin:.15rem 0;font-size:1.6rem}.billing-hero p{margin:0;opacity:.82}.billing-nav{display:flex;gap:.35rem;overflow:auto;margin-top:1rem;padding:.45rem;border:1px solid #dce6ec;border-radius:.8rem;background:#fff}.billing-nav a{display:flex;align-items:center;gap:.35rem;min-width:max-content;padding:.5rem .65rem;border-radius:.55rem;color:#5d6e7d;font-size:.7rem}.billing-nav a.router-link-exact-active{background:#eaf5fb;color:#197da4}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:.7rem;margin-top:1rem}.metrics article{display:flex;align-items:center;gap:.65rem;padding:.8rem;border:1px solid #dce6ec;border-radius:.75rem;background:#fff}.metrics article>span{display:grid;place-items:center;width:38px;height:38px;border-radius:10px;background:#eaf5fb;color:#187da5}.metrics small,.metrics strong{display:block}.metrics strong{font-size:1.15rem}.billing-card{overflow:hidden;margin-top:1rem;border:1px solid #dce6ec;border-radius:.9rem;background:#fff}.billing-card>header{display:flex;align-items:center;justify-content:space-between;padding:1rem;border-bottom:1px solid #e3e9ed}.billing-card h2{font-size:1rem}.filters{display:flex;gap:.5rem}.filters input{width:250px}.state{display:grid;place-items:center;padding:4rem;color:#788896;text-align:center}.state>i{font-size:2.5rem}.records{display:grid}.records article{display:flex;align-items:center;gap:.7rem;padding:.8rem 1rem;border-bottom:1px solid #e7ecef}.records article>span{display:grid;place-items:center;width:38px;height:38px;border-radius:10px;background:#eef6fa;color:#227da5}.records article>div:nth-child(2){min-width:0;flex:1}.records small,.records strong,.records p{display:block;margin:0}.records small{color:#26805d;font-size:.62rem}.records p{color:#798895;font-size:.68rem}.amount{text-align:right}@media(max-width:850px){.metrics{grid-template-columns:repeat(2,1fr)}.billing-card>header{align-items:flex-start;flex-direction:column;gap:.7rem}.filters{width:100%}.filters input{width:100%}}@media(max-width:550px){.billing-hero{align-items:flex-start;flex-direction:column;gap:.8rem}.metrics{grid-template-columns:1fr}.filters{flex-direction:column}.records article{align-items:flex-start;flex-wrap:wrap}.amount{margin-left:46px;text-align:left}}</style>
